create function sales_test_assert(v boolean,label text) returns void language plpgsql as $$ begin if v is distinct from true then raise exception 'TEST FAILED: %',label; end if; end $$;
select set_config('test.p','{"userId":"20000000-0000-4000-8000-000000000001","allowedProjectIds":["10000000-0000-4000-8000-000000000001"]}',false);
select set_config('test.project','10000000-0000-4000-8000-000000000001',false);
select sales_save_contact(current_setting('test.p')::jsonb,'{"projectId":"10000000-0000-4000-8000-000000000001","id":"30000000-0000-4000-8000-000000000001","companyName":"Bilbolaget","branchName":"Hässleholm","email":"info@example.se","websiteUrl":null,"history":"not_contacted","pilotMonths":12,"historySource":"Operatören bekräftade ingen tidigare kontakt","confirmed":true,"excluded":false,"suppressed":false,"expectedVersion":0}');
select sales_save_contact(current_setting('test.p')::jsonb,'{"projectId":"10000000-0000-4000-8000-000000000001","id":"30000000-0000-4000-8000-000000000002","companyName":"Bilbolaget","branchName":"Malmö","email":"info@example.se","websiteUrl":null,"history":"not_contacted","pilotMonths":12,"historySource":"Kontrollerad","confirmed":true,"excluded":false,"suppressed":false,"expectedVersion":0}');
select sales_save_offer(current_setting('test.p')::jsonb,'{"projectId":"10000000-0000-4000-8000-000000000001","id":"40000000-0000-4000-8000-000000000001","senderEmail":"info@handlarborsen.se","offerText":"12 månader gratis","productFacts":["Stängd svensk marknadsplats för bilhandlare"],"freeMonths":12,"confirmed":true}');
select set_config('test.input','{"projectId":"10000000-0000-4000-8000-000000000001","conversationId":"50000000-0000-4000-8000-000000000001","contactIds":["30000000-0000-4000-8000-000000000001"],"offerRevisionId":"40000000-0000-4000-8000-000000000001","idempotencyKey":"first"}',false);
update sales_contacts set data=data||'{"pilotMonths":12}';
select sales_save_offer(current_setting('test.p')::jsonb,'{"projectId":"10000000-0000-4000-8000-000000000001","id":"40000000-0000-4000-8000-000000000002","senderEmail":"info@handlarborsen.se","offerText":"6 månader gratis","productFacts":["Marknadsplats för bilhandlare"],"freeMonths":6,"confirmed":true}');
do $$ begin perform sales_prepare_job(current_setting('test.p')::jsonb,current_setting('test.input')::jsonb||'{"idempotencyKey":"wrong-tier","offerRevisionId":"40000000-0000-4000-8000-000000000002"}');raise exception 'TEST FAILED: wrong pilot tier accepted';exception when object_not_in_prerequisite_state then null;end $$;
select set_config('test.job',(sales_prepare_job(current_setting('test.p')::jsonb,current_setting('test.input')::jsonb)->>'id'),false);
select sales_test_assert(sales_prepare_job(current_setting('test.p')::jsonb,current_setting('test.input')::jsonb)->>'id'=current_setting('test.job'),'same request returns same job');
do $$ begin perform sales_prepare_job(current_setting('test.p')::jsonb,current_setting('test.input')::jsonb||'{"contactIds":["30000000-0000-4000-8000-000000000002"]}'); raise exception 'TEST FAILED: conflicting replay accepted'; exception when unique_violation then null; end $$;
do $$ begin perform sales_prepare_job('{"userId":"20000000-0000-4000-8000-000000000002","allowedProjectIds":["10000000-0000-4000-8000-000000000001"]}',current_setting('test.input')::jsonb); raise exception 'TEST FAILED: foreign owner'; exception when no_data_found then null; end $$;
select sales_test_assert((select count(*)=2 from sales_contacts),'shared mailbox keeps two branches');
select sales_enroll_worker(current_setting('test.p')::jsonb,jsonb_build_object('projectId',current_setting('test.project'),'workerId','60000000-0000-4000-8000-000000000001','tokenHash',repeat('a',64)));
select set_config('test.claim',sales_claim_job(repeat('a',64),'{}')::text,false);
select sales_test_assert(sales_claim_job(repeat('a',64),'{}')->'ref'='null'::jsonb,'second claimer gets no running job');
select set_config('test.ref',(current_setting('test.claim')::jsonb->'ref')::text,false);
select sales_commit_research(repeat('a',64),current_setting('test.ref')::jsonb||'{"contactId":"30000000-0000-4000-8000-000000000001","evidence":null,"question":null}');
select sales_reserve_attempt(repeat('a',64),current_setting('test.ref')::jsonb||'{"contactId":"30000000-0000-4000-8000-000000000001","attemptId":"70000000-0000-4000-8000-000000000001"}');
update projects set execution_paused=true where id=current_setting('test.project')::uuid;
do $$ begin perform sales_reserve_attempt(repeat('a',64),current_setting('test.ref')::jsonb||'{"contactId":"30000000-0000-4000-8000-000000000001","attemptId":"70000000-0000-4000-8000-000000000002"}'); raise exception 'TEST FAILED: pause ignored'; exception when object_not_in_prerequisite_state then null; end $$;
update projects set execution_paused=false where id=current_setting('test.project')::uuid;
select set_config('test.draft','{"contactId":"30000000-0000-4000-8000-000000000001","contactVersion":1,"offerRevisionId":"40000000-0000-4000-8000-000000000001","senderEmail":"info@handlarborsen.se","toEmail":"info@example.se","subject":"En fråga","body":"Vill ni prova 12 månader gratis?","evidenceIds":[],"questions":[]}',false);
select sales_commit_drafts(repeat('a',64),current_setting('test.ref')::jsonb||jsonb_build_object('drafts',jsonb_build_array(current_setting('test.draft')::jsonb)));
select sales_test_assert((select count(*)=1 from sales_draft_revisions),'one persisted draft');
select sales_commit_drafts(repeat('a',64),current_setting('test.ref')::jsonb||jsonb_build_object('drafts',jsonb_build_array(current_setting('test.draft')::jsonb)));
select sales_test_assert((select count(*)=1 from sales_draft_revisions),'completion replay is idempotent');
select set_config('test.old',(select id::text from sales_draft_revisions limit 1),false);
select set_config('test.old_run',(select run_id::text from sales_draft_revisions limit 1),false);
select set_config('test.old_approval',(select approval_id::text from sales_draft_revisions limit 1),false);
select sales_save_revision(current_setting('test.p')::jsonb,jsonb_build_object('projectId',current_setting('test.project'),'revisionId',current_setting('test.old'),'draft',current_setting('test.draft')::jsonb||'{"body":"Ändrad fråga om 12 månader gratis"}'));
select sales_test_assert(resolve_approval(current_setting('test.old_approval')::uuid,current_setting('test.old_run')::uuid,current_setting('test.project')::uuid,'approved',null)='LOST','superseded generic approval cannot win');
select sales_test_assert((select count(*)=1 from sales_draft_revisions where is_current),'one current version');
insert into sales_contacts select '30000000-0000-4000-8000-000000000003',project_id,1,data||'{"id":"30000000-0000-4000-8000-000000000003","email":"limits@example.se"}',now() from sales_contacts where id='30000000-0000-4000-8000-000000000001';
select set_config('test.input',(current_setting('test.input')::jsonb||'{"contactIds":["30000000-0000-4000-8000-000000000003"]}')::text,false);
select set_config('test.job2',(sales_prepare_job(current_setting('test.p')::jsonb,current_setting('test.input')::jsonb||'{"idempotencyKey":"limits"}')->>'id'),false);
select set_config('test.ref2',(sales_claim_job(repeat('a',64),'{}')->'ref')::text,false);
select sales_commit_research(repeat('a',64),current_setting('test.ref2')::jsonb||'{"contactId":"30000000-0000-4000-8000-000000000003","evidence":null,"question":null}');
do $$ declare i integer;begin for i in 1..10 loop perform sales_reserve_attempt(repeat('a',64),current_setting('test.ref2')::jsonb||jsonb_build_object('contactId','30000000-0000-4000-8000-000000000003','attemptId',gen_random_uuid()));end loop;
begin perform sales_reserve_attempt(repeat('a',64),current_setting('test.ref2')::jsonb||jsonb_build_object('contactId','30000000-0000-4000-8000-000000000003','attemptId',gen_random_uuid()));raise exception 'TEST FAILED: eleventh attempt accepted';exception when object_not_in_prerequisite_state then null;end;end $$;
select sales_control_job(current_setting('test.p')::jsonb,jsonb_build_object('projectId',current_setting('test.project'),'jobId',current_setting('test.job2')));
do $$ begin perform sales_commit_drafts(repeat('a',64),current_setting('test.ref2')::jsonb||jsonb_build_object('drafts',jsonb_build_array(current_setting('test.draft')::jsonb)));raise exception 'TEST FAILED: cancelled completion accepted';exception when serialization_failure then null;end $$;
select set_config('test.expired',(sales_prepare_job(current_setting('test.p')::jsonb,current_setting('test.input')::jsonb||'{"idempotencyKey":"expired"}')->>'id'),false);
select set_config('test.expired_ref',(sales_claim_job(repeat('a',64),'{}')->'ref')::text,false);
update sales_jobs set lease_until=now()-interval '1 second' where id=current_setting('test.expired')::uuid;
select sales_claim_job(repeat('a',64),'{}');
select sales_test_assert((select status='reconciling' from sales_jobs where id=current_setting('test.expired')::uuid),'expired work is not replayed');
select sales_revoke_worker(current_setting('test.p')::jsonb,jsonb_build_object('projectId',current_setting('test.project'),'workerId','60000000-0000-4000-8000-000000000001'));
do $$ begin perform sales_claim_job(repeat('a',64),'{}');raise exception 'TEST FAILED: revoked worker accepted';exception when no_data_found then null;end $$;
update sales_contacts set data=data||'{"history":"contacted"}' where id='30000000-0000-4000-8000-000000000003';
do $$ begin perform sales_prepare_job(current_setting('test.p')::jsonb,current_setting('test.input')::jsonb||'{"idempotencyKey":"already-contacted"}');raise exception 'TEST FAILED: prior contact ignored';exception when object_not_in_prerequisite_state then null;end $$;
do $$ begin update sales_offer_revisions set data=data||'{"freeMonths":6}';raise exception 'TEST FAILED: offer was mutable';exception when object_not_in_prerequisite_state then null;end $$;
select sales_test_assert(not has_function_privilege('authenticated','sales_prepare_job(jsonb,jsonb)','execute'),'browser cannot forge principal');
select sales_test_assert(not has_table_privilege('anon','sales_contacts','select'),'anon has no contact access');
select set_config('request.jwt.claim.sub','20000000-0000-4000-8000-000000000002',false);
set role authenticated;
select sales_test_assert((select count(*)=0 from sales_contacts),'nonowner sees no contacts');
reset role;
select 'PASS sales replay, ownership, branch identity, claim, pause, immutable review and RLS';
